components.script:
// Feed it your own level, for example the RMS of an AnalyserNode frame.
const meter = document.getElementById("demo-level");
function setLevel(level) {
  meter.style.setProperty("--level", level);
  meter.setAttribute("aria-valuenow", level.toFixed(2));
}
document.getElementById("demo-level-input").addEventListener("input", (e) => setLevel(Number(e.target.value)));

import { mountLivingTable } from "signal-design/js";

const root = document.getElementById("living-table-demo");
const table = mountLivingTable(root);
const preview = document.getElementById("living-table-widths");
for (const button of preview.querySelectorAll("[data-living-width]")) {
  button.addEventListener("click", () => {
    const value = button.dataset.livingWidth;
    table.resize({ width: value === "fluid" ? null : Number(value) });
  });
}

import { createChart } from "signal-design/charts";

const core = createChart(document.querySelector("#demo-core canvas"), {
  preset: "core",                      // bandwidth over latency, one time axis
  bucketSeconds: 10, live: 2, envelope: 60,
  series: [
    { label: "Core ↓", data: down },   // [{ x: ms, y: Mbps }]
    { label: "Core ↑", data: up },
    { label: "Core → MDF RTT", unit: " ms", data: rtt, min: jitterLow, max: jitterHigh },
  ],
});
core.append({ "Core ↓": [{ x: Date.now(), y: 4200 }] });

import { createChart } from "signal-design/charts";

createChart(canvas, {
  type: "line",            // line | area | step | bar | hbar | histogram | scatter
  labels: ["Mon", "Tue", "Wed", "Thu", "Fri"],
  unit: " ms",
  series: [{ label: "p50", data: [82, 80, 91, 88, 79] }, { label: "p95", data: [190, 210, 260, 230, 200] }],
  markers: [{ axis: "y", value: 250, label: "SLO", tone: "warning" }],
});

// One <i> per square; the CSS reads --v (0–1) on the heatmap, data-s on the waffle, data-state on the uptime bar.
document.getElementById("demo-heat").innerHTML = Array.from({ length: 7 * 24 }, () => `<i style="--v: ${Math.random().toFixed(2)}"></i>`).join("");
document.getElementById("demo-waffle").innerHTML =
  '<i data-s="1"></i>'.repeat(42) + '<i data-s="2"></i>'.repeat(31) + '<i data-s="3"></i>'.repeat(19) + "<i></i>".repeat(8);
document.getElementById("demo-uptime").innerHTML = '<i data-state="ok"></i>'.repeat(57) + '<i data-state="degraded"></i><i data-state="down"></i><i data-state="ok"></i>';

const feed = document.getElementById("demo-feed");
const jump = document.getElementById("demo-jump");
feed.scrollTop = feed.scrollHeight;
feed.addEventListener("scroll", () => {
  const away = feed.scrollHeight - feed.scrollTop - feed.clientHeight > 80;
  if (away === jump.hidden) jump.hidden = !away;
});
jump.querySelector("button").addEventListener("click", () => feed.scrollTo({ top: feed.scrollHeight, behavior: "smooth" }));

import { mountAscii } from "signal-design/ascii";
import * as piece from "ascii-magic-art/pieces/spinning-torus.js";

const stage = document.querySelector("#ascii-stage");
let art = mountAscii(stage.querySelector(".sd-ascii"), piece, { at: 1.4 });

// A look redraws the piece in other characters.
art.destroy();
art = mountAscii(stage.querySelector(".sd-ascii"), piece, { at: 1.4, look: "dots" });

// Still until the stage says it is busy.
stage.setAttribute("aria-busy", "true");

import { mountAscii } from "signal-design/ascii";
import * as piece from "ascii-magic-art/pieces/ci-pipeline.js";

const panel = document.querySelector("#ascii-job");
mountAscii(panel.querySelector(".sd-ascii"), piece, { at: 4 });

// The art follows aria-busy on its closest ancestor that has it.
panel.setAttribute("aria-busy", "true");   // plays
panel.removeAttribute("aria-busy");        // holds the frame it is on

import { mountAscii } from "signal-design/ascii";
import * as piece from "ascii-magic-art/pieces/tunnel.js";

const card = document.querySelector("[data-ascii-card]");
mountAscii(card.querySelector(".sd-ascii"), piece, { at: 3 });

// Hover or focus plays the card, leaving holds it.
card.addEventListener("pointerenter", () => card.setAttribute("aria-busy", "true"));
card.addEventListener("pointerleave", () => card.removeAttribute("aria-busy"));

import { mountAscii } from "signal-design/ascii";
import * as piece from "ascii-magic-art/pieces/sleeping-cat.js";

mountAscii(document.querySelector(".sd-empty .sd-ascii"), piece, { at: 3 });

import { mountAscii } from "signal-design/ascii";
import * as piece from "ascii-magic-art/pieces/empty-payment-failed.js";

// data-tone paints the brightest grey of the piece with the tone.
const art = document.querySelector('.sd-ascii[data-tone="danger"]');
mountAscii(art, piece, { at: 4 });

// React: the state lives in the component; no data-sd-* attributes.
function Toolbar() {
  const [view, setView] = useState("list");
  const [open, setOpen] = useState(false);
  const [liked, setLiked] = useState(false);
  return (
    <>
      <div className="sd-seg sd-seg-inline" role="group" aria-label="View">
        {["list", "board"].map((v) => (
          <button key={v} type="button" aria-pressed={view === v} onClick={() => setView(v)}>{v}</button>
        ))}
      </div>
      <button className="sd-btn sd-btn-sm" aria-expanded={open} aria-controls="details" onClick={() => setOpen(!open)}>Details</button>
      <div className="sd-reactions">
        <button aria-pressed={liked} onClick={() => setLiked(!liked)}>👍 <b>{2 + (liked ? 1 : 0)}</b></button>
      </div>
      <div className="sd-expand" id="details" data-open={open || undefined}><div>…</div></div>
    </>
  );
}

import { mountCountdown } from "signal-design/js";
const root = document.getElementById("demo-countdown");
const countdown = mountCountdown(root);
let remainingMs = 5000;
let startedAt = null;
root.addEventListener("sd:countdown", ({ detail }) => {
  document.getElementById("countdown-state").textContent = detail.state;
  if (detail.state === "complete") { remainingMs = 0; startedAt = null; }
});
function set(running) {
  if (startedAt !== null) remainingMs = Math.max(0, remainingMs - (performance.now() - startedAt));
  startedAt = running ? performance.now() : null;
  countdown.set({ remainingMs, running });
}
set(false);
document.getElementById("countdown-resume").onclick = () => set(true);
document.getElementById("countdown-pause").onclick = () => set(false);
document.getElementById("countdown-resync").onclick = () => {
  remainingMs = 5000;
  startedAt = null;
  set(false);
};

import { mountFeed, hotkeys } from "signal-design/js";
const root = document.getElementById("demo-feed");
root.addEventListener("sd:feed", ({ detail }) => {
  document.getElementById("feed-above").textContent = `${detail.aboveCount} above`;
});
const feed = mountFeed(root);
const off = hotkeys({ j: () => feed.move(1), k: () => feed.move(-1),
  "g t": () => feed.newest(), n: () => feed.oldest() },
  { target: root, sequenceTimeout: 900, enabled: () => !root.hidden });
document.getElementById("feed-oldest").onclick = () => feed.oldest();
document.getElementById("feed-newest").onclick = () => feed.newest();
let order = 3;
document.getElementById("feed-insert").onclick = () => {
  feed.beforeUpdate();
  const row = document.createElement("article");
  row.className = "sd-row";
  row.dataset.id = `activity-${++order}`;
  row.dataset.order = String(order);
  row.textContent = `Activity ${order} received`;
  root.prepend(row);
  feed.afterUpdate();
};
